begin;
create table if not exists t_knowledge_point_backup_20261028_97 as
select * from t_knowledge_point where id in (22565,22586,22589,22593,22597,22601,22602,22642,22663,22664,22668,22669,22681,22692,22700,22710,22721,22727,22740,22757,22775,22787,22807,22902,22914,22918,22925,22926,22927,22928,22929,22930,22936,22947,22977,23036,23037,23599,23664,23915,23921,23956,23976,24029,24122,25127,25128,25136,25254,25292,25293,25308,25309,25783,26040,26249,26250,26447,26760,27004,27377,27401,27406,27419,27424,27425,27426,27444,27770,28153,28173,28175,28181,28182,28233,28322,28323,28339,28378,28514,28524,28526,28527,28529,28530,29187,29196,29197,29308,29324,29325,29326,29347,29359,29360,29361,29425,29432,29433,29467,29469,32003);

update t_knowledge_point set title = $kp$ADSL MODEM 与 PC 机的连接$kp$, content = $kp$住户端：电话线接入 ADSL MODEM，ADSL MODEM 通过以太网卡与 PC 机相连。局端：电话交换机经数字通信线路接入电话局，实现用户接入。$kp$, section = '' where id = 22565;
update t_knowledge_point set title = $kp$中继器$kp$, content = $kp$中继器（Repeater），也称转发器，把接收到的信号整形放大后继续传送，起到信号“接力”的作用。当安装局域网而物理距离超过线路规定的长度时，可用它延伸。中继器工作在物理层，只放大信号，不能隔离不同网段之间不必要的网络流量，但结构简单、价格便宜、安装容易。一般的中继器只能连接两个距离较近的以太网，使用光纤中继器再加上光纤传输线路，则可以连接两个距离相隔较远的局域网。$kp$, section = '' where id = 22586;
update t_knowledge_point set title = $kp$以太网的工作原理$kp$, content = $kp$拓扑结构为总线型；采用广播方式通信；数据传输以帧（frame）为单位，一次传输一帧；采用带冲突检测的载波侦听多路访问（CSMA/CD）方法，保证任何时候只有一个结点发送消息。总线两端各接一个终端器，中间依次连接各台计算机。$kp$, section = '' where id = 22589;
update t_knowledge_point set title = $kp$共享式以太网$kp$, content = $kp$以集线器（Hub）为中心构成，集线器的功能是广播信号和放大信号；根据实际需要，一个以太网中可以有多个集线器。拓扑结构为总线型，采用广播方式通信，采用带冲突检测的载波侦听多路访问（CSMA/CD）方法，保证任何时候只有一个结点发送消息。总线结构以太网的特点是：维护方便，增删结点容易，轻负载（结点少或信息发送不频繁）时效率较高，重负载时网络性能急剧下降。$kp$, section = '' where id = 22593;
update t_knowledge_point set title = $kp$同轴电缆（有线电视传输介质）的优点$kp$, content = $kp$具有很高的容量；抗电子干扰能力强；使用频分多路复用技术同时传送多个电视频道；由于有线电视系统的设计容量远高于现在使用的电视频道数目，未使用的带宽（频道）可被用来传输数据；数字信号和模拟信号可以同时传送，互相不会发生冲突。$kp$, section = '' where id = 22597;
update t_knowledge_point set title = $kp$FDDI 网的工作原理$kp$, content = $kp$拓扑结构为双环；传输介质为光纤；传输速率为 100Mb/s；覆盖范围较大、传输速率高，用于构造局域网的主干部分。FDDI 有特有的帧格式，与其他局域网互连时，要通过网桥或路由器才能实现。$kp$, section = '' where id = 22601;
update t_knowledge_point set title = $kp$交换式以太网的工作原理$kp$, content = $kp$以交换式集线器（以太网交换器）为中心构建，网络中的每个结点通过网卡和网线连接在交换器上。拓扑结构为星型。每一个结点都独享一定的带宽（10Mb/s 或 100Mb/s），多对结点可同时通信；而总线式局域网中所有结点共享一定的带宽。交换器可按层次方式互相连接，构成多层次的局域网。$kp$, section = '' where id = 22602;
update t_knowledge_point set title = $kp$同轴电缆的分类$kp$, content = $kp$同轴电缆由内层导线、绝缘体、金属屏蔽层（地线）、外绝缘层（套管）构成。按用途分为两类：基带同轴电缆（50Ω），以前在以太网中使用；宽带同轴电缆（75Ω），有线电视网使用。$kp$, section = '' where id = 22642;
update t_knowledge_point set title = $kp$交换式以太网$kp$, content = $kp$以以太网交换机（简称交换机）为中心构成，拓扑结构为星型。它与总线式结构的区别是：连接在交换机上的每一台计算机各自独享一定的带宽。$kp$, section = '' where id = 22663;
update t_knowledge_point set title = $kp$交换式以太网与总线结构以太网的区别$kp$, content = $kp$交换式以太网：连接在交换器上的每一个结点各自独享一定的带宽。总线式以太网：连接在集线器上的所有结点共享一定的带宽（总线的带宽）。交换式以太网可按工作组交换器、部门交换器、中央交换器分层组网，提供 10Mb/s、100Mb/s 至桌面，1000Mb/s 至中央服务器的连接。$kp$, section = '' where id = 22664;
update t_knowledge_point set title = $kp$同轴电缆$kp$, content = $kp$粗同轴电缆的端口连接器是 AUI，细同轴电缆的端口连接器是 BNC。同轴电缆的传输距离可达几公里甚至几十公里。$kp$, section = '' where id = 22668;
update t_knowledge_point set title = $kp$同轴电缆——利用电流传输信息$kp$, content = $kp$同轴电缆有基带同轴电缆和宽带同轴电缆两种。前者曾经使用在计算机局域网中，现在已被无屏蔽双绞线和光纤所取代；后者即常用的有线电视电缆，主要用于传输电视信号，最大传输距离可达几公里甚至几十公里。$kp$, section = '' where id = 22669;
update t_knowledge_point set title = $kp$用集线器构建以太网$kp$, content = $kp$以集线器为中心，网络中的每个结点通过网卡和网线（一般是 5 类双绞线）连接到集线器；每块网卡都有一个全球唯一的 MAC 地址（48 位二进制数），传输速率为 10Mbps、100Mbps、1Gbps。集线器简称 Hub，用来连接网络中各个结点，基本功能是把一个端口接收到的信息向所有端口分发出去，并能对接收到的信号进行放大，以扩大网络的传输距离，起着中继器的作用。总线结构以太网的特点是：维护方便，增删结点容易；轻负载（结点少或信息发送不频繁）时效率较高，重负载时网络性能急剧下降，因此以太网并不适合实时性要求较高的环境。$kp$, section = '' where id = 22681;
update t_knowledge_point set title = $kp$集线器$kp$, content = $kp$集线器简称 Hub，用来连接网络中各个结点。基本功能：把一个端口接收到的信息向所有端口分发出去，能对接收到的信号进行放大，以扩大网络的传输距离，起着中继器的作用。$kp$, section = '' where id = 22692;
update t_knowledge_point set title = $kp$交换式以太网的构建$kp$, content = $kp$以以太网交换机（Ethernet switch）为中心构成。以太网交换机是一种高速电子交换器，连接在交换机上的所有计算机均可同时相互通信（例如 1→3、2→5、4→6 同时传输）。与总线式以太网相比：集线器向所有计算机广播数据帧、由计算机选择接收，交换机按 MAC 地址把数据帧直接发送给指定的计算机；总线式一次只允许一对计算机传输数据帧，交换式允许多对计算机同时传输；总线式实质上是总线型拓扑结构，交换式为星型拓扑结构；总线式所有计算机共享一定的带宽，交换式每台计算机各自独享一定的带宽。不同速率的以太网交换机可以按层次方式互相连接，构成“校—院系—室、组”的多层次局域网，光纤传输介质的长度可达几公里。$kp$, section = '' where id = 22700;
update t_knowledge_point set title = $kp$千（万）兆位以太网$kp$, content = $kp$在学校、企业等单位内部，借助以太网交换机可按性能高低以树状方式将许多小型以太网互相连接，构成“公司（单位）—部门—工作组”的多层次以太局域网（校园网、企业网等）。用户的计算机与所在工作组的交换机连接，低层（工作组、部门）的交换机以 100Mbps、1000Mbps 甚至 10Gbps 的速度与高层的中央交换机连接，中央交换机的总带宽可达每秒几十至几百 G 以上，光纤传输介质的长度可达几公里。网络服务器通过 100Mbps 或 1000Mbps 的传输线路与中央交换机直接连接，可发挥其最大潜力，同时为单位内许多用户服务，这种局域网称为千（万）兆位以太网。$kp$, section = '' where id = 22710;
update t_knowledge_point set title = $kp$网桥$kp$, content = $kp$网桥（Bridge）用来连接两个同类型的网段，比中继器多了帧过滤功能。网桥检查每一信息帧的发送地址和目的地址：如果这两个地址都在网桥的同一网段，该帧就不会被发送到另一个网段；只有在发送地址和目的地址不在同一网段的情况下，网桥才把该帧转发给另一个网段，从而降低整个网络的通信负荷。网桥工作在网络的链路层，实现两个网络链路层的互连。$kp$, section = '' where id = 22721;
update t_knowledge_point set title = $kp$总线式以太网（集线器组网）$kp$, content = $kp$以集线器（Hub）为中心，每台计算机通过以太网卡和双绞线连接到集线器的一个端口，通过集线器与其他结点相互通信。集线器把一个端口接收到的帧向所有端口分发出去，并对信号进行放大，以扩大网络的传输距离，起着中继器的作用。$kp$, section = '' where id = 22727;
update t_knowledge_point set title = $kp$以太网交换器（交换式集线器）$kp$, content = $kp$基本功能：用来构建交换式局域网，使得每个端口可以独享一定带宽，并且实现点对点式的通信方式。通过以太网交换器可按层次方式互相连接，构成多层次的局域网。以太网交换器工作在网络的链路层。$kp$, section = '' where id = 22740;
update t_knowledge_point set title = $kp$常用局域网$kp$, content = $kp$局域网按照所使用的传输介质，可分为有线网和无线网；按照各种设备互连的拓扑结构，可分为星型网、环型网、总线网、混合网等；按照传输介质所使用的访问控制方法，可分为以太网（Ethernet）、FDDI 网和令牌网等。不同类型的局域网采用不同的 MAC 地址格式和数据帧格式，使用不同的网卡和协议。现在广泛使用的是以太网，FDDI 网和令牌网已很少使用。$kp$, section = '' where id = 22757;
update t_knowledge_point set title = $kp$以太网帧长度$kp$, content = $kp$以太网帧是数据链路层的封装：网络层的数据包被加上帧头和帧尾，成为可以被数据链路层识别的数据帧。帧头和帧尾的字节数固定不变，但被封装的数据包大小不同，因此帧长在 64～1518 字节之间（不含 8 字节的前导码）。$kp$, section = '' where id = 22775;
update t_knowledge_point set title = $kp$光纤取代金属电缆$kp$, content = $kp$双绞线和同轴电缆需要耗费大量金属材料，成本高；而光纤的传输性能已远远超过了金属电缆，成本也已大幅降低。目前各种通信（广播）系统和计算机网络的主干线路中，光纤已全面取代了电缆。$kp$, section = '' where id = 22787;
update t_knowledge_point set title = $kp$ATM 交换式局域网$kp$, content = $kp$使用 ATM 交换机构建的局域网。ATM 交换机采用 ATM 交换技术，既能提供分组交换方式的常规数据传输服务，又能提供电路交换方式的实时数据传输服务（如音频、视频等应用），数据传输速率高（每个端口独享 155Mbps 或 622Mbps），能方便地与 ATM 广域网进行互连。ATM 局域网一般用作校园网或企业网的骨干网。$kp$, section = '' where id = 22807;
update t_knowledge_point set title = $kp$交换式以太网$kp$, content = $kp$以太网交换器（交换式集线器）内部有一个核心交换式背板，采用一个纯粹的交换系统代替传统集线器的共享介质中继网段。连接在交换器上的每一个结点各自独享一定的带宽（10Mb/s 或 100Mb/s），为数据帧从一个端口到另一个任意端口的转发提供了低时延、低开销的通路。交换式集线器可以按层次方式互相连接，构成工作组—部门—公司的多层次的局域网。$kp$, section = '' where id = 22902;
update t_knowledge_point set title = $kp$介质访问控制方法$kp$, content = $kp$带冲突检测的载波侦听多路访问（CSMA/CD）方法，用于总线结构局域网，以太网采用此方法。标记环法，用于环型结构局域网。$kp$, section = '' where id = 22914;
update t_knowledge_point set title = $kp$以太网与 MAC 地址$kp$, content = $kp$介质访问地址（简称 MAC 地址）：为实现总线上任意两个结点之间的通信，局域网中每个结点的网卡都有一个唯一的地址（48 位二进制数）。发送结点发送一帧信息时，帧中必须包含自己的 MAC 地址和接收结点的 MAC 地址。每次通信时，连接在总线上的所有结点的网卡都要检测信息帧中的 MAC 地址，来决定是否应该接收该信息帧。信息帧的接收方可以是一个结点，也可以是一组结点（称为组播），甚至是网络上所有其他的结点（称为广播）。$kp$, section = '' where id = 22918;
update t_knowledge_point set title = $kp$总线式以太网$kp$, content = $kp$以集线器（Hub）为中心，每台计算机通过以太网卡和双绞线连接到集线器的一个端口，通过集线器与其他结点相互通信。以太网数据帧包含接收方（目的）MAC 地址、发送方（源）MAC 地址、有效载荷（传输的数据）和校验信息。$kp$, section = '' where id = 22925;
update t_knowledge_point set title = $kp$交换式以太网$kp$, content = $kp$以以太网交换机（Ethernet switch）为中心构成。以太网交换机是一种高速电子交换器，连接在交换机上的所有计算机均可同时相互通信（例如 1→3、2→5、4→6 同时传输）。与总线式以太网的区别：集线器向所有计算机广播数据帧、由计算机选择接收，交换机按 MAC 地址把数据帧直接发送给指定的计算机；总线式一次只允许一对计算机传输数据帧，交换式允许多对计算机同时传输；总线式实质上是总线型拓扑结构，交换式为星型拓扑结构；总线式所有计算机共享一定的带宽，交换式每台计算机各自独享一定的带宽。$kp$, section = '' where id = 22926;
update t_knowledge_point set title = $kp$千（万）兆位以太网$kp$, content = $kp$不同速率的以太网交换机可以按层次方式互相连接，构成“校—院系—室、组”的多层次的局域网，光纤传输介质的长度可达几公里。典型结构中，Internet 经路由器、防火墙接入万兆交换机，再经光缆连接各楼宇的千兆交换机、图书馆、实验室等，服务器和网管工作站也接入中央交换机。$kp$, section = '' where id = 22927;
update t_knowledge_point set title = $kp$MAC 地址$kp$, content = $kp$以太网中，每台计算机都需要安装一块网卡，每块以太网卡都有一个全球唯一的编号，称为 MAC 地址，也称为该计算机的物理地址。MAC 地址用 48 位表示，例如 00-02-AC-39-FE-AE（十六进制）。前三个字节（高 24 位）由 IEEE 分配给厂家，后三个字节（低 24 位）由厂家分配给网卡。网卡即计算机的通信控制器，网络中每台计算机都应安装网卡；网卡的功能大多已集成在芯片组中，即所谓的“集成网卡”。$kp$, section = '' where id = 22928;
update t_knowledge_point set title = $kp$以太网帧格式$kp$, content = $kp$在以太网上传输数据也采用将数据分组（包）的方法，以太网上的分组称为“MAC 帧”。每个 MAC 帧包含接收方（目的）MAC 地址、发送方（源）MAC 地址、有效载荷（发送的数据）和 CRC 循环冗余校验码，校验码可提高数据传输的可靠性。网卡从网络上每收到一个 MAC 帧，就检查其中的 MAC 地址：如果是送往本机的帧，则收下进行处理；否则将此帧丢弃，不做任何处理。$kp$, section = '' where id = 22929;
update t_knowledge_point set title = $kp$以太网数据帧$kp$, content = $kp$以太网数据帧依次由接收方（目的）MAC 地址、发送方（源）MAC 地址、有效载荷（传输的数据）和校验信息组成。$kp$, section = '' where id = 22930;
update t_knowledge_point set title = $kp$使用中继器进行互连$kp$, content = $kp$中继器（Repeater）也称转发器，把接收到的信号整形放大后继续传送，起到一个信号“接力”的作用。它用于连接同类型的两个局域网或者延伸一个局域网的范围，当安装一个局域网而物理距离又超过了线路的规定长度时，就可以用它进行延伸。中继器工作在网络的物理层，只放大信号，不能隔离不同网段之间不必要的网络数据流量，但结构简单、价格便宜、安装容易。$kp$, section = '' where id = 22936;
update t_knowledge_point set title = $kp$光纤分布式数字接口网（FDDI）$kp$, content = $kp$FDDI 网络可以覆盖较大的范围，能支持较高的数据传输速率（100Mb/s），实用中常用于构造局域网的主干部分，把许多不同部门的局域网互相连接起来。由于 FDDI 的帧格式和其他常用局域网的帧格式不同，因此与其他局域网进行互连时，需要通过网关或路由器才能实现。$kp$, section = '' where id = 22947;
update t_knowledge_point set title = $kp$双绞线和同轴电缆$kp$, content = $kp$原理：利用电流（电压）传输信息。双绞线按类别分为 3 类线（10Mb/s）、5 类线（100Mb/s）、6 类线（200Mb/s）；按屏蔽情况分为无屏蔽双绞线（UTP）和屏蔽双绞线（STP）。$kp$, section = '' where id = 22977;
update t_knowledge_point set title = $kp$网卡按产品形态分类$kp$, content = $kp$分为独立网卡和集成网卡（由芯片组实现网卡功能）。台式机多使用独立网卡，便携机则常用集成网卡或专用便携网卡。$kp$, section = '' where id = 23036;
update t_knowledge_point set title = $kp$网卡按传输速率分类$kp$, content = $kp$10Mbps 网卡（10Base-T）、100Mbps 网卡（100Base-T）、10/100Mbps 自适应网卡、100/1000Mbps 自适应网卡。$kp$, section = '' where id = 23037;
update t_knowledge_point set title = $kp$光纤通信$kp$, content = $kp$利用光纤传导光信号进行通信的技术。发端实现信号的电—光转换，收端实现信号的光—电转换。全光网（AON）不进行光—电、电—光转换，速度提高、成本降低，是信息高速公路的基础。优点是可靠性强、传输频带非常宽、通信容量大（速度最快）、抗雷电和电磁干扰及抗辐射能力强、无串音干扰、保密性强、不易被窃听或截取数据、传输损耗小、通信距离长；缺点是精确连接两根光纤比较困难，超长距离传输会有信号损耗，因此要加入光中继器。$kp$, section = '' where id = 23599;
update t_knowledge_point set title = $kp$光导纤维（光纤）$kp$, content = $kp$光纤通过光波传输信息，由折射率较高的纤芯和折射率略低的包层组成，在信号的发送端和接收端之间需要进行电—光、光—电的信号转换。优点是通信容量大、传输距离远（无中继通信距离可达几十甚至上百公里）、不会受高压线和雷电电磁感应的影响、抗核辐射能力强、几乎不漏光、保密性强、重量轻、便于运输和铺设。$kp$, section = '' where id = 23664;
update t_knowledge_point set title = $kp$光纤与光缆$kp$, content = $kp$光导纤维（光纤）利用全反射传输光波：当光线的入射角足够大时，在纤芯与包层的界面上发生全反射，光被不断反射回纤芯，如此重复，光就沿着光纤传播下去。光纤由纤芯、包层和保护层构成。

光缆由多根光纤组合而成，自内向外包括多根光纤、防止光泄漏的吸收外壳、起保护作用的防护层和外绝缘层。

光纤通信是利用光波携带信息、在光纤中传输以达到通信目的。发送端把电信号经驱动电路送入光源（半导体激光器或发光二极管），发出光信号并经光调制器调制；调制后的光信号在光纤中传输，为补偿线路损耗，每隔一定距离要接入中继器；接收端把放大后的光信号由光检测器（半导体光电管）检测、解调，再转换成电信号输出。$kp$, section = '' where id = 23915;
update t_knowledge_point set title = $kp$光纤通信原理$kp$, content = $kp$光纤通信利用光波携带信息，在光纤中传输，达到通信目的。

工作过程：数字信号（电信号）驱动光源（半导体激光器或发光二极管），发出光信号；调制后的光信号通过光纤传输，为补偿光纤线路的损耗，每隔一定距离要接入中继器；光信号经放大后由光检测器（半导体光电管）检测、解调，再转换成电信号输出。

从功能上可划分为发送单元（电/光转换）、传输单元（光纤与中继器）和接收单元（光/电转换）。$kp$, section = '' where id = 23921;
update t_knowledge_point set title = $kp$同轴电缆的频分多路复用$kp$, content = $kp$同轴电缆利用频率分割原理，实现在有线信道上的多路复用。

过程：发信端把各路信号分别对不同载波频率进行调制，搬移到不同频带后，同时在同一线路上传输；收信端对线路信号放大后，按相反顺序用滤波器分开各路信号，再经解调恢复原来的信息。

例如有线电视信号通过同轴电缆入户，同一根电缆同时承载多个电视台的信号，家中多台电视机可接收相同或不同的电视台信号，每台电视机接收哪个信号由其选台器决定。在同轴电缆中，不同电视信号占用不同频率，互不干扰。$kp$, section = '' where id = 23956;
update t_knowledge_point set title = $kp$对称电缆（双绞线）$kp$, content = $kp$特点：数字信号、模拟信号均可传输；各线对采用双绞线，减少了线对之间的串扰；频带较电话线宽，每对线可传输 60 路电话信号，多线对能提供上千个话路，适用于干线通信。

缺点：容易受到外部高频电磁波干扰，线路本身也会产生一定噪声，误码率较高；如用作数据通信网络的传输介质，每隔一定距离需要使用中继器或放大器。

常见应用：电话系统（模拟信号）、局域网（数字信号）。$kp$, section = '' where id = 23976;
update t_knowledge_point set title = $kp$有线载波通信的传输介质$kp$, content = $kp$有线载波通信采用的传输介质有架空明线、对称电缆和同轴电缆，传输的信号为电信号（模拟信号或数字信号）。

架空明线（二线制标准电话线路）：传输模拟信号，如话音；频带窄（300 Hz～3400 Hz），传输容量有限，可传 3～12 路电话；易受气候变化影响，通信质量不稳定，多用于业务量较小的次要传输线路。常见应用为电话系统。

对称电缆（4 对双绞线）：分为有屏蔽双绞线（STP）和无屏蔽双绞线（UTP）。按类别分，三类线速率为 10 Mb/s，五类线为 100 Mb/s，六类线可达 1000 Mb/s。连接计算机使用 RJ-45 接头。$kp$, section = '' where id = 24029;
update t_knowledge_point set title = $kp$光纤通信的优点$kp$, content = $kp$通信容量大：一束光每秒能传输 2.5 Gb 或 10 Gb 的信息。
传输距离远：无中继距离可超过几十公里。
保密性强：信息不易泄露。$kp$, section = '' where id = 24122;
update t_knowledge_point set title = $kp$双绞线$kp$, content = $kp$双绞线由两根相互绝缘的导线绞合成匀称的螺纹状，作为一条通信线路。双绞线分为有屏蔽双绞线和无屏蔽双绞线两种，前者支持较远距离的数据传送，误码率低，但价格高；后者用于局域网，又分为 3 类、4 类、5 类线，其中 5 类线的传输速率可达 100 Mb/s，但传输距离一般不超过 100 米。

双绞线容易受到外部高频电磁波的干扰，线路本身也会产生一定噪声，误码率高，因此每隔一定距离就要用一台中继器放大信号。双绞线通常用作局域网的传输介质，其连接到计算机上的接口叫 RJ-45（俗称水晶头）。$kp$, section = '' where id = 25127;
update t_knowledge_point set title = $kp$双绞线——利用电流传输信息$kp$, content = $kp$双绞线由两根相互绞合成均匀螺纹状的导线组成，多根这样的双绞线捆在一起，外面包上护套，就构成双绞线电缆。双绞线有屏蔽双绞线（STP）和无屏蔽双绞线（UTP）两种：前者在双绞线外面加上了用金属丝编织成的屏蔽层，可用于较远距离的数据传送；后者价格便宜，在计算机局域网中普遍采用。

双绞线的缺点是易受外部高频电磁波干扰，误码率较高，通常只在建筑物内部使用。双绞线既可传输模拟信号，也可传输数字信号，连接到计算机上的接口叫 RJ-45（俗称水晶头）。$kp$, section = '' where id = 25128;
update t_knowledge_point set title = $kp$以太网使用的传输介质$kp$, content = $kp$同轴电缆：早期使用，速率 10 Mb/s 的以太网曾采用，价格较高。
双绞线（5 类线）：大量用于速率为 10 Mb/s 和 100 Mb/s 的以太网。
光纤：用于速率为千兆（1 Gb/s）和万兆（10 Gb/s）的以太网。

双绞线和 RJ-45 插头（水晶头）是目前以太网使用最多的传输介质。$kp$, section = '' where id = 25136;
update t_knowledge_point set title = $kp$传输介质：金属导体与光导纤维$kp$, content = $kp$传输介质分为金属导体（传输电流）和光导纤维（传输光波）两类。

双绞线：由 8 根导线两两绞合而成，绞合可有效减少线对之间的串扰；利用电流、电压传输信号；缺点是易受外部高频电磁波干扰、误码率较高；传输距离一般不超过 100 米。应用于局域网布线，接头为 RJ-45 水晶头。按有无屏蔽层分为屏蔽双绞线（STP，适合较远距离传输）和无屏蔽双绞线（UTP，价格便宜、使用普遍）。五类线速率为 100 Mb/s，六类线可达 1000 Mb/s。

光导纤维（光波）见光纤与光缆相关条目。$kp$, section = '' where id = 25254;
update t_knowledge_point set title = $kp$同轴电缆的结构与应用$kp$, content = $kp$组成：内导线、绝缘体、金属屏蔽层、外绝缘层。
特点：成本较高，但抗干扰能力强、屏蔽效果好，传输特性好，可传输数字信号，传输距离长。
应用：有线电视接入、传输有线电视信号、固定电话中继线路。
分类：基带同轴电缆用于局域网中的以太网；宽带同轴电缆用于有线电视。$kp$, section = '' where id = 25292;
update t_knowledge_point set title = $kp$光纤与光缆的特点$kp$, content = $kp$光纤（光导纤维）的组成：纤芯、包层、涂覆层（屏蔽外部光源的干扰）、保护层。
特点：通信容量大、传输距离远、抗电磁干扰能力强、抗辐射、保密性强；传输速率最高可达 1000 Mb/s；长距离传输仍需中继器。

光缆包含多根光纤，由多根光纤、防止光泄漏的吸收外壳、防护层和外绝缘层组成，同样具有通信容量大、传输距离远、抗电磁干扰、抗辐射、保密性强的特点。

光纤是有线传输介质而非无线介质，光纤中传输的是光信号，基于光的全反射原理；光纤常用于网络主干部分，局域网中也可使用。FDDI 主要采用光纤作为传输介质，一般用于主干网。$kp$, section = '' where id = 25293;
update t_knowledge_point set title = $kp$MAC 帧格式与网卡$kp$, content = $kp$局域网中的数据传输：采用分组交换技术，把每台计算机要传输的数据分成帧，即 MAC 帧；一次只能传输 1 帧，不允许一次传任意多的数据；数据帧以时分多路复用方式共享传输介质。

MAC 帧的组成：有效载荷（真正传输的数据）、源计算机 MAC 地址、目的计算机 MAC 地址、控制信息、校验信息。校验信息用于确认接收的数据是否正确，若出错，源计算机将这一帧数据重发。

网卡：网络上每台设备（PC、手机、服务器、打印机）都有网络接口卡；它是连接计算机与传输介质的接口，负责收发、封装、拆封数据帧，功能由芯片组实现；网卡与局域网之间通过电缆、双绞线、无线电波以串行方式传输；不同类型的网络需使用不同类型的网卡，即使都是以太网也是如此。网卡分独立网卡和集成网卡。

MAC 地址：通常用十六进制表示，共 48 位二进制。它是全球唯一的地址码，又称物理地址。前三个字节（高位 24 位）由 IEEE 分配给厂家，后三个字节（低位 24 位）由厂家分配给网卡。以太网主机间通信通过 MAC 地址识别。查看本机 MAC 地址可用 winipcfg 命令（适用于 Windows 9x）或 ipconfig 命令（适用于 Windows 2000/XP）。$kp$, section = '' where id = 25308;
update t_knowledge_point set title = $kp$共享式以太网与交换式以太网$kp$, content = $kp$以太网分为共享式以太网和交换式以太网。千（万）兆位以太网适合学校、企业等内部单位使用，速率为 1000 Mb/s（1 Gb/s）或 10 Gb/s。以太网大多采用交换机。

共享式以太网（总线型以太网）：是最早使用的以太局域网，使用 10/100 Mb/s 自适应网卡，须用以太网卡才能接入网络。以集线器（HUB）为中心，计算机通过网卡和两端装有 RJ-45 插头的 5 类双绞线连接到集线器，网络中可以有多个集线器。集线器的功能是：将收到的数据帧以广播方式发出、对信号进行放大、扩大网络传输距离，起中继器的作用。所有计算机通过以太网卡和双绞线连到一条公用的传输线（总线）上实现互相通信；集线器向所有计算机广播数据帧，由计算机选择接收；一次只允许一对计算机传输数据；采用总线拓扑结构，所有计算机共享一定带宽，只适合计算机数目很少的网络。

交换式以太网：以以太网交换机（一种高速电子开关）为中心，交换机按 MAC 地址将数据帧直接发送给指定计算机；每台计算机独享一定带宽，允许多对计算机同时传输数据；采用星型拓扑结构，点到点通信；传输介质为双绞线、光纤。

以太网组网：借助交换机按性能高低以树状方式连接小型以太网，出口处先接防火墙，再接路由器，最后接入 Internet。使用的网卡没有区别，区别在于传输介质（双绞线、光纤或无线）和传输速率（10 Mb/s、100 Mb/s 或 1000 Mb/s）。目前最多的是千兆网卡和 10/100 Mb/s 自适应网卡。$kp$, section = '' where id = 25309;
update t_knowledge_point set title = $kp$网线连接方式与网卡分类$kp$, content = $kp$按 T568B 标准制作双绞线：主机到交换机/集线器用直通线，路由器到交换机/集线器用直通线；主机到主机、路由器到路由器、交换机到交换机、集线器到集线器、路由器到主机用交叉线。

网卡：分为集成网卡和独立网卡等。按支持的传输速率分类，主要分为 10 Mb/s 网卡、100 Mb/s 网卡、10/100 Mb/s 自适应网卡和 1000 Mb/s 网卡四类。

10 Mb/s 和 100 Mb/s 网卡仅支持对应的传输速率。在使用非屏蔽双绞线 UTP 作为传输介质时，通常 10 Mb/s 网卡与 3 类 UTP 配合使用，100 Mb/s 网卡与 5 类 UTP 相连接。10/100 Mb/s 自适应网卡由网卡自动检测网络的传输速率，保证网络中两种不同传输速率的兼容性。随着局域网传输速率的不断提高，1000 Mb/s 网卡大多应用于高速服务器中。$kp$, section = '' where id = 25783;
update t_knowledge_point set title = $kp$光缆的结构$kp$, content = $kp$光缆采用光波传输，包含多根光纤。其结构自内向外为：多根光纤、防止光泄漏的吸收外壳、起保护作用的防护层、外绝缘层。$kp$, section = '' where id = 26040;
update t_knowledge_point set title = $kp$同轴电缆的分类与特性$kp$, content = $kp$同轴电缆的芯线为铜质导线，外包一层绝缘材料，再外面是由细铜丝组成的网状导体，最外面加一层塑料保护膜。芯线与网状导体同轴，故名同轴电缆。这种结构使它具有高带宽和很好的噪声抑制特性。

按特性阻抗数值的不同，同轴电缆分为 50 Ω 基带同轴电缆和 75 Ω 宽带同轴电缆。前者用于传输基带数字信号，是早期局域网的主要传输媒体；后者是 CATV 中的标准传输电缆，其上传输的信号采用频分复用的宽带模拟信号。$kp$, section = '' where id = 26249;
update t_knowledge_point set title = $kp$光纤的结构与分类$kp$, content = $kp$与铜质介质相比，光纤具有明显优势：光纤不会向外界辐射电磁信号，因此使用光纤介质的网络在安全性、可靠性和传输速率等性能方面都有很大提高；制造光纤的主要原料是硅，成本很低。

光纤由单根玻璃光纤（纤芯）、紧靠纤芯的包层以及塑料保护涂层组成。为使用光纤传输信号，光纤两端必须配有光发射机和光接收机，光发射机完成电信号到光信号的转换，光接收机完成光信号到电信号的转换。

按光在光纤中的传播方式，分为多模光纤和单模光纤。单模光纤纤芯极细，直径一般小于 10 μm；多模光纤纤芯较粗，直径一般为 50 μm。多模光纤是光纤通信最原始的技术，已逐渐被淘汰；单模光纤通信带宽大，更适用于远程通信。$kp$, section = '' where id = 26250;
update t_knowledge_point set title = $kp$Web 2.0 的含义$kp$, content = $kp$Web 2.0 又称第二代互联网，是相对于 Web 1.0 的新的时代，指利用 Web 平台、由用户主导生成内容的互联网产品模式，以区别于传统由网站雇员主导生成内容的模式。它更注重交互性，是信息技术发展引发网络革命所带来的以人为本的创新模式在互联网领域的体现，也是由专业人员织网到所有用户参与织网的创新民主化进程。

Web 2.0 模式下的互联网应用具有去中心化、开放、共享等显著特点：
1）用户分享：不受时间和地域限制地分享各种观点，用户既能获取需要的信息，也能发布自己的观点。
2）信息聚合：信息在网络上不断积累，不会丢失。
3）以兴趣为聚合点的社群：聚集的是对某个或某些问题感兴趣的群体，无形中产生了细分市场。
4）开放的平台、活跃的用户：平台对用户开放，用户因兴趣保持较高的忠诚度并积极参与。

Web 2.0 网站与 Web 1.0 没有绝对界限：Web 2.0 技术可以成为 Web 1.0 网站的工具，一些在 Web 2.0 概念之前诞生的网站本身也具有 Web 2.0 特性，例如 B2B 电子商务网站的免费信息发布和网络社区类网站的内容也来源于用户。$kp$, section = '' where id = 26447;
update t_knowledge_point set title = $kp$有线局域网的定义$kp$, content = $kp$有线局域网是把分布在数公里范围内不同物理位置的计算机设备连在一起，在网络软件的支持下实现相互通信和资源共享的网络系统。$kp$, section = '' where id = 26760;
update t_knowledge_point set title = $kp$更改计算机名与工作组$kp$, content = $kp$在“系统属性”对话框中选择“计算机名”选项卡，可看到完整的计算机名和工作组成员，并可更改网络属性。操作步骤：
（1）单击【更改】按钮，打开“计算机名称更改”对话框。
（2）在“计算机名”文本框中输入新的计算机名；单击【其他】按钮，可在打开的对话框中修改域名；修改后单击【确定】按钮关闭对话框。
（3）在“隶属于”选项组中选择计算机隶属类型：若隶属于工作组，则在“工作组”文本框中输入工作组名；若隶属于域，则在“域”文本框中输入域名。
（4）单击【确定】按钮完成操作。$kp$, section = '' where id = 27004;
update t_knowledge_point set title = $kp$网络接口和硬件层设备$kp$, content = $kp$网络接口和硬件层的主要设备包括中继器、集线器和网卡，它们工作在 OSI 模型与 TCP/IP 模型的底层。$kp$, section = '' where id = 27377;
update t_knowledge_point set title = $kp$MAC 地址的组成$kp$, content = $kp$每块以太网卡都有一个全球唯一的 MAC 地址，MAC 地址由 6 个字节（48 位二进制）组成。$kp$, section = '' where id = 27401;
update t_knowledge_point set title = $kp$有线通信的传输介质$kp$, content = $kp$有线通信的传输介质主要有三种：
① 双绞线：网口为 RJ-45 接口，传输距离有限，双绞的目的是减少电磁干扰。
② 同轴电缆：如有线电视线。
③ 光纤：价格高，传输距离远，没有电磁干扰，保密性好，长距离传输需要使用中继器。

光纤中传递的是光信号，因此传输过程中涉及电/光、光/电转换。光纤中传递的不是电磁信号，所以不受电磁感应的影响，噪声干扰小，可靠性高。$kp$, section = '' where id = 27406;
update t_knowledge_point set title = $kp$局域网的数据帧$kp$, content = $kp$局域网采用时分多路复用技术，把传输的数据分成小块，称为数据帧，每个节点每次传输 1 个帧。数据帧中包含发送端的 MAC 地址和接收端的 MAC 地址。

数据帧的基本字段：发送方 MAC 地址、接收方 MAC 地址、真正的数据、校验数据。

网卡又称网络适配器。$kp$, section = '' where id = 27419;
update t_knowledge_point set title = $kp$同类局域网的数据格式$kp$, content = $kp$同一种类型的局域网使用相同的网卡，MAC 地址格式相同，数据帧格式也相同。$kp$, section = '' where id = 27424;
update t_knowledge_point set title = $kp$共享式以太网的结构$kp$, content = $kp$共享式以太网以集线器（HUB）为中心，采用总线型结构，所有计算机共享带宽，以广播方式通信。$kp$, section = '' where id = 27425;
update t_knowledge_point set title = $kp$交换式以太网与多层次以太网$kp$, content = $kp$交换式以太网以以太网交换机为中心，采用星型结构，每台计算机独享带宽，采用点到点通信。

千（万）兆位以太网借助不同速率的交换机，以树状方式将许多小型以太网连接起来，构成“公司—部门—工作组—计算机”的多层次以太局域网，如校园网、企业网等。$kp$, section = '' where id = 27426;
update t_knowledge_point set title = $kp$光纤通信中的电光转换$kp$, content = $kp$光纤通信以光纤作为传输介质，发送端把电信号转换为光信号送入光纤，接收端把光信号还原为电信号输出。$kp$, section = '' where id = 27444;
update t_knowledge_point set title = $kp$MAC 地址的长度$kp$, content = $kp$MAC 地址有 48 位，即 6 个字节。$kp$, section = '' where id = 27770;
update t_knowledge_point set title = $kp$有线通信的三种传输介质$kp$, content = $kp$① 双绞线：网口为 RJ-45 接口，传输距离有限，双绞的目的是减少电磁干扰。
② 同轴电缆：如有线电视线。
③ 光纤：价格高，传输距离远，没有电磁干扰，保密性好，长距离传输需要用中继器。

光纤中传递的是光信号，所以传输过程中涉及电/光、光/电转换。光纤中传递的不是电磁信号，因此不受电磁感应的影响，噪声干扰小，可靠性高。$kp$, section = '' where id = 28153;
update t_knowledge_point set title = $kp$不同局域网的 MAC 地址格式$kp$, content = $kp$不同类型局域网的 MAC 地址格式各不相同。局域网的数据传输方法见数据帧相关条目。$kp$, section = '' where id = 28173;
update t_knowledge_point set title = $kp$数据帧的字段组成$kp$, content = $kp$数据帧中包含发送端的 MAC 地址和接收端的 MAC 地址。

字段依次为：发送方 MAC 地址、接收方 MAC 地址、真正的数据、CRC 校验数据。

网卡又称网络适配器。$kp$, section = '' where id = 28175;
update t_knowledge_point set title = $kp$共享式以太网的特点$kp$, content = $kp$共享式以太网以集线器（HUB）为中心，采用总线型结构，所有计算机共享带宽，以广播方式通信。$kp$, section = '' where id = 28181;
update t_knowledge_point set title = $kp$交换式以太网与千（万）兆位以太网$kp$, content = $kp$交换式以太网以以太网交换机为中心，采用星型结构，每台计算机独享带宽，采用点到点通信。

千（万）兆位以太网借助不同速率的交换机，以树状方式将许多小型以太网连接起来，构成“公司—部门—工作组—计算机”的多层次以太局域网，如校园网、企业网等。$kp$, section = '' where id = 28182;
update t_knowledge_point set title = $kp$MAC 地址无法改变$kp$, content = $kp$MAC 地址固化在网卡中，无法改变。$kp$, section = '' where id = 28233;
update t_knowledge_point set title = $kp$MAC 地址写死在网卡中$kp$, content = $kp$MAC 地址写死在网卡中，不可改变。$kp$, section = '' where id = 28322;
update t_knowledge_point set title = $kp$总线型以太网$kp$, content = $kp$总线型以太网以集线器（HUB）为中心，采用总线型结构，所有计算机共享带宽，以广播方式通信。$kp$, section = '' where id = 28323;
update t_knowledge_point set title = $kp$总线式以太网与 CSMA/CD 协议$kp$, content = $kp$总线式以太网采用 CSMA/CD 介质访问控制协议决定如何使用通信介质，交换式以太网兼容该协议。$kp$, section = '' where id = 28339;
update t_knowledge_point set title = $kp$节点的物理地址$kp$, content = $kp$每个节点都有一个唯一的物理地址，即介质访问控制地址，简称 MAC 地址。$kp$, section = '' where id = 28378;
update t_knowledge_point set title = $kp$总线式以太网采用CSMA/CD解决冲突$kp$, content = $kp$总线式以太网采用 CSMA/CD 协议解决冲突。计算机网络也可采用频分多路复用技术。$kp$, section = '' where id = 28514;
update t_knowledge_point set title = $kp$有线传输介质包括双绞线、同轴电缆和光纤$kp$, content = $kp$光纤属于有线传输介质，有线传输介质包括双绞线、同轴电缆和光纤。$kp$, section = '' where id = 28524;
update t_knowledge_point set title = $kp$光纤通常用于网络的骨干部分$kp$, content = $kp$光纤通常用于网络的骨干部分。$kp$, section = '' where id = 28526;
update t_knowledge_point set title = $kp$FDDI采用光纤作为传输介质，属于环形拓扑$kp$, content = $kp$FDDI 网一般用于主干网，主要采用光纤作为传输介质，属于环形拓扑结构。光纤中可以传输模拟信号。$kp$, section = '' where id = 28527;
update t_knowledge_point set title = $kp$常见局域网与共享式以太网的结构$kp$, content = $kp$常见的局域网有以太网、FDDI、令牌网。共享式以太网以集线器（HUB）为中心，拓扑结构为星型结构。$kp$, section = '' where id = 28529;
update t_knowledge_point set title = $kp$共享式与交换式以太网使用相同的网卡$kp$, content = $kp$共享式以太网与交换式以太网使用相同的网卡，MAC 帧格式相同。$kp$, section = '' where id = 28530;
update t_knowledge_point set title = $kp$树形局域网根结点故障的影响$kp$, content = $kp$树形局域网采用千兆/万兆以太网。当根结点发生故障时，可能导致整个网络瘫痪，其他结点所在的子网也可能部分瘫痪。$kp$, section = '' where id = 29187;
update t_knowledge_point set title = $kp$双绞线的原理、优缺点与应用$kp$, content = $kp$1) 双绞的目的：降低各线对之间的电磁串扰。
2) 优点：数字信号、模拟信号均可传输；各线对采用双绞，减少了线对之间的串扰；频带较电话线宽，每对线可传输 60 路电话信号，多线对能提供上千个话路，适用于干线通信。
3) 缺点：容易受到外部高频电磁波干扰（多用于建筑物内部），线路本身会产生一定噪声，误码率较高；每隔一定距离（约 100 米）需使用中继器或放大器。
4) 常见应用：电话系统（模拟信号）、局域网（数字信号）。
5) 目前大多数 10/100 Mbps 以太网采用的传输介质是 5 类双绞线。$kp$, section = '' where id = 29196;
update t_knowledge_point set title = $kp$光纤的原理、优缺点、分类与应用$kp$, content = $kp$1) 物理原理：全反射（光纤弯曲时也能传导光信号）。
2) 优点：通信容量大，数据传输速率高；绝缘体不受高压线和雷电的电磁干扰；抗核辐射能力强；保密性强，不易被窃听或截取数据；重量轻，便于运输和铺设；传输损耗小，无中继通信距离长（可达几千公里）；原材料 SiO₂ 资源丰富，可节约有色金属。
3) 缺点：精确连接两根光纤比较困难；相关通信设备的价格无明显优势。
4) 分类：单模光纤（远距离通信）、多模光纤（近距离通信，如局域网）。
5) 光纤中采用的多路复用技术：波分多路复用。
6) 全光网：在传输及交换过程中始终以光的形式进行，不经过光/电、电/光转换和光中继。$kp$, section = '' where id = 29197;
update t_knowledge_point set title = $kp$交换式以太网采用星型拓扑$kp$, content = $kp$交换式以太网的拓扑结构是星型结构，采用点到点通信，以交换机为中心，传输介质为双绞线、光纤。$kp$, section = '' where id = 29308;
update t_knowledge_point set title = $kp$总线型与星型以太网的特点$kp$, content = $kp$以太网速率为 10 Mbps。
总线型网络：传输介质为同轴电缆，采用广播式通信，所有节点共享带宽；某个节点故障，整个网络不通。
星型以太网：中央设备为集线器，传输介质为双绞线，采用广播式通信，所有节点共享带宽；某个节点发生故障不影响整个网络，除非中央设备故障。$kp$, section = '' where id = 29324;
update t_knowledge_point set title = $kp$交换式以太网各节点独占带宽$kp$, content = $kp$交换式以太网采用星型结构，所有节点独占带宽，有利于扩展网络带宽；交换机发送数据时使用分组交换技术（存储转发）。$kp$, section = '' where id = 29325;
update t_knowledge_point set title = $kp$令牌环网需持有令牌才能发送数据$kp$, content = $kp$令牌环网为环型网络，节点必须拿到令牌才可以传输数据，并且一个网络中只有一个令牌。$kp$, section = '' where id = 29326;
update t_knowledge_point set title = $kp$局域网的应用场景$kp$, content = $kp$应用场景：单位内部的专用小交换机（PABX）组成局域网；集线器（HUB）连接工作站组成网络等。$kp$, section = '' where id = 29347;
update t_knowledge_point set title = $kp$常用传输介质与以太网标准参数$kp$, content = $kp$常用传输介质：
同轴电缆细缆 RG-58：最大段长 185 m，速率 10 Mbps；安装容易、成本低、抗干扰性较强。
同轴电缆粗缆 RG-11：最大段长 500 m，速率 10 Mbps；安装较难、成本低、抗干扰性强。
宽带同轴电缆 RG-59：传输距离大于 10 km，速率 100～150 Mbps；传输模拟信号，常采用频分多路复用方式传输信息。
屏蔽双绞线（3 类/5 类）：最大段长 100 m，速率 16/100 Mbps；比非屏蔽双绞线笨重，令牌环网常用。
非屏蔽双绞线（5 类/超 5 类/6 类）：最大段长 100 m，速率 100/155/200 Mbps；价格便宜、安装容易，适用于结构化综合布线，短距离内甚至可达 1 Gbps。
多模光纤：最大段长 2 km，速率 100～1000 Mbps；电磁干扰小、传输速率高、误码率小、延迟低。
单模光纤：最大段长 2～10 km，速率 1～10 Gbps；与多模光纤相比，速率更高、传输距离更长、成本更高、芯线更细，常采用波分多路复用方式传输信息。

以太网标准：
10Base5：粗同轴电缆，500 m，每段 100 个结点，早期电缆，已废弃。
10Base2：细同轴电缆，185 m，每段 30 个结点，不需集线器。
10Base-T：非屏蔽双绞线，100 m，每段 1024 个结点，最便宜的系统。
10Base-F：光纤，2000 m，每段 1024 个结点，适合楼间使用。
100Base-T4：非屏蔽双绞线，100 m，3 类线，4 对。
100Base-TX：非屏蔽双绞线，100 m，5 类线，全双工。
100Base-FX：光纤，2000 m，全双工，长距离。
1000Base-SX：光纤，550 m，多模光纤。
1000Base-LX：光纤，5000 m，单模或多模光纤。
1000Base-CX：屏蔽双绞线，25 m，2 对 STP。
1000Base-T：非屏蔽双绞线，100 m，5 类线，4 对。$kp$, section = '' where id = 29359;
update t_knowledge_point set title = $kp$小型企业网络设备选型与Windows对等网$kp$, content = $kp$小型企业可选用二层/三层区域交换机（接入、汇聚、核心）、接入路由器等。
组建 Windows 对等网：对等网采用分散管理的方式，网络中的每台计算机既作为客户机又可作为服务器来工作，每个用户都管理自己机器上的资源。$kp$, section = '' where id = 29360;
update t_knowledge_point set title = $kp$有线局域网的组建与配置步骤$kp$, content = $kp$① 网线制作及测试：使用 568B 线序制作，制作后随时用测线仪测试，保证每条线连通。
② 硬件连接：安装网卡并安装网卡驱动程序，对网卡进行相关调试，确保网卡工作正常；用制作好的网线连接交换机和计算机，观察交换机和计算机的指示灯，正常点亮即可，未点亮需即时检查。
③ 配置网络：配置 IP 地址前先规划网络使用的 IP 地址范围，建议使用 C 类地址，最好是 C 类保留地址，如 192.168.0.1～192.168.0.10。
④ 网络测试：用 ping 命令测试能否 ping 通，能 ping 通说明整个网络已经调试完成。$kp$, section = '' where id = 29361;
update t_knowledge_point set title = $kp$光纤的特点与信号转换$kp$, content = $kp$有线通信介质包括双绞线、同轴电缆、光纤。光纤是重要考点：① 价格高、传输距离远、没有电磁干扰；② 保密性好，传输损耗小，无中继距离长；③ 光纤中传递的是光信号，传输过程中涉及电/光、光/电转换。$kp$, section = '' where id = 29425;
update t_knowledge_point set title = $kp$局域网采用时分多路复用，数据块称为MAC帧$kp$, content = $kp$局域网采用时分多路复用技术，传输数据分成的小块叫“MAC 帧”，每个节点每次传输 1 个帧。$kp$, section = '' where id = 29432;
update t_knowledge_point set title = $kp$总线式以太网采用CSMA/CD介质访问控制协议$kp$, content = $kp$总线式以太网采用 CSMA/CD 介质访问控制协议决定如何使用通信介质，交换式以太网兼容这个协议。$kp$, section = '' where id = 29433;
update t_knowledge_point set title = $kp$以太网的分类及共享式与交换式的区别$kp$, content = $kp$以太网分为：以集线器（HUB）构成的总线型以太网、交换式以太网（星形）、双环形（FDDI）。
重点：HUB 以太网和交换式以太网的区别：总线型以太网可以一对多，交换式以太网一对一；前者以集线器（HUB）为中心，后者以交换机为中心；前者为总线型，后者为星形；前者共享带宽，后者独享带宽。
一个以太网中能使用多个集线器。$kp$, section = '' where id = 29467;
update t_knowledge_point set title = $kp$中继器的作用$kp$, content = $kp$中继器把接收到的信号放大后继续传送，起到信号“接力”的作用。
单位用户接入方式：局域网；家庭用户接入方式：电话拨号（ADSL）、光纤接入。$kp$, section = '' where id = 29469;
update t_knowledge_point set title = $kp$局域网组网过程$kp$, content = $kp$硬件连接与安装：制作 4 条标准双绞网线并注意线序；将网卡插入 PCI 白色插槽；安装网卡驱动程序，检查网卡冲突并解决（卸载重装、升级驱动程序、重新设置 IRQ 级别和 I/O 地址）；完成物理连接。软件安装与设置：添加客户端、服务和协议，包括 Microsoft 网络客户端（支持登录对等网）、Microsoft 网络的文件和打印机共享（支持文件、打印机共享）、TCP/IP（支持上网）、IPX/SPX（支持联网游戏）、NetBEUI（Windows 网络必备）；设置 TCP/IP 协议，指定 IP 地址、子网掩码、默认网关和 DNS 服务器，或选择自动获取 IP 地址；设置计算机标识及分组。$kp$, section = '' where id = 32003;

